import { duration, instant } from '@absoluteui/core';
import { SessionWarningDialog } from '@absoluteui/components/session-warning-dialog';

const warning = SessionWarningDialog.create({ expiresAt: instant(Date.now() + 15 * 60_000), warnBefore: duration(2 * 60_000) });
warning.element.addEventListener('aui-extend', () => {
  void fetch('/api/session/refresh', { method: 'POST' }).then(async (r) => {
    const body: unknown = await r.json();
    if (typeof body === 'object' && body !== null && 'expiresAt' in body && typeof body.expiresAt === 'number') {
      warning.update({ expiresAt: instant(body.expiresAt) });
    }
  });
});
warning.element.addEventListener('aui-sign-out', () => {
  location.assign('/sign-out');
});

import { instant } from '@absoluteui/core';
import { SessionWarningDialog } from '@absoluteui/components/session-warning-dialog';

const warning = SessionWarningDialog.create({
  expiresAt: instant(Date.parse('2026-03-08T12:00:00Z')),
  title: 'Still working?',
  message: 'Unsaved changes are kept for 10 minutes after sign-out.',
});
warning.open();
